// HomeServiceHandler is an implementation of the mavio.cloud.v1.HomeService service.
type HomeServiceHandler interface {
	// GetHome gives the account's Home and the invitations it received.
	GetHome(context.Context, *v1.GetHomeRequest) (*v1.GetHomeResponse, error)
	// CreateHome creates a Home the account administers; it must not belong
	// to one.
	CreateHome(context.Context, *v1.CreateHomeRequest) (*v1.CreateHomeResponse, error)
	// DissolveHome dissolves the administrator's Home: full members become
	// its friends and managed accounts are deleted.
	DissolveHome(context.Context, *v1.DissolveHomeRequest) (*v1.DissolveHomeResponse, error)
	// InviteToHome invites a full account, offering access records on the
	// administrator's servers; it needs the administrator's Mavio Pass.
	InviteToHome(context.Context, *v1.InviteToHomeRequest) (*v1.InviteToHomeResponse, error)
	// CancelHomeInvitation withdraws an invitation.
	CancelHomeInvitation(context.Context, *v1.CancelHomeInvitationRequest) (*v1.CancelHomeInvitationResponse, error)
	// AcceptHomeInvitation joins a Home, leaving the account's current one,
	// and puts the offered access records in effect.
	AcceptHomeInvitation(context.Context, *v1.AcceptHomeInvitationRequest) (*v1.AcceptHomeInvitationResponse, error)
	// DeclineHomeInvitation declines an invitation.
	DeclineHomeInvitation(context.Context, *v1.DeclineHomeInvitationRequest) (*v1.DeclineHomeInvitationResponse, error)
	// LeaveHome leaves the full member's Home; it becomes the
	// administrator's friend.
	LeaveHome(context.Context, *v1.LeaveHomeRequest) (*v1.LeaveHomeResponse, error)
	// RemoveMember removes a member: a full member becomes the
	// administrator's friend, a managed account is deleted with its data.
	RemoveMember(context.Context, *v1.RemoveMemberRequest) (*v1.RemoveMemberResponse, error)
	// CreateManagedAccount creates a managed account in the administrator's
	// Home.
	CreateManagedAccount(context.Context, *v1.CreateManagedAccountRequest) (*v1.CreateManagedAccountResponse, error)
	// UpdateManagedAccount changes a managed account's display name and
	// restriction profile.
	UpdateManagedAccount(context.Context, *v1.UpdateManagedAccountRequest) (*v1.UpdateManagedAccountResponse, error)
	// ConvertManagedAccount makes a managed account a full account with an
	// e-mail address and a password; it keeps its ID, data, access and Home.
	ConvertManagedAccount(context.Context, *v1.ConvertManagedAccountRequest) (*v1.ConvertManagedAccountResponse, error)
	// SetPin sets or clears a PIN: a full account's own, or a managed
	// account's by its Home's administrator.
	SetPin(context.Context, *v1.SetPinRequest) (*v1.SetPinResponse, error)
}

